def test_get_nfts_by_ids_chunks_metadata_batches_to_alchemy_limit(
    mock_httpx_client, mock_settings
):
    captured_batches: list[list[dict]] = []
    mock_httpx_client.post.side_effect = _create_mock_post_side_effect(
